INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','6abb64cb-65ee-4d05-99c3-6f800bb38c5b',NULL,2001,9,11,'Society & Human Rights',65,'{"id":"6abb64cb-65ee-4d05-99c3-6f800bb38c5b","ad_day":11,"ad_date":null,"ad_year":2001,"bs_date":null,"country":"United States","sources":[],"ad_month":9,"category":"Society & Human Rights","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"The September 11 attacks, a series of coordinated terrorist attacks killing 2,977 people using four aircraft hijacked by 19 members of al-Qaeda . Two aircraft crash into the World Trade Center in New York City, a third crashes into The Pentagon in Arlington County, Virginia, and a fourth into a field near Shanksville, Pennsylvania .","title_ne":"सेप्टेम्बर ११ को आक्रमण, अल-कायदाका १९ सदस्यहरूले अपहरण गरेका चार विमानहरू प्रयोग गरेर २,९७७ जनाको मृत्यु हुने समन्वित आतंकवादी हमलाहरूको श्रृंखला। दुई विमान न्यूयोर्क शहरको वर्ल्ड ट्रेड सेन्टरमा ठोक्किए, तेस्रो भर्जिनियाको आर्लिंगटन काउन्टीमा रहेको पेन्टागनमा ठोक्किए र चौथो पेन्सिलभेनियाको शान्क्सभिल नजिकैको खेतमा ठोक्किए।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:40.152741+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/September_11_attacks","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:40.152741+00:00","source_name":"User-provided historical dataset","country_code":"US","image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=September%2011%20attacks&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"September 11 attacks","source_record_id":"0911-2001-e-1dkcsuc"