INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('on_this_day_events','72f63ce5-c800-4fdd-996a-dd8d560d2f96',NULL,2001,5,15,'Arts, Literature & Entertainment',65,'{"id":"72f63ce5-c800-4fdd-996a-dd8d560d2f96","ad_day":15,"ad_date":null,"ad_year":2001,"bs_date":null,"country":null,"sources":[],"ad_month":5,"category":"Arts, Literature & Entertainment","metadata":{"source_dataset":"lennovative/history_alert (Wikipedia-derived)","source_license":"Wikipedia-derived; retain linked-page attribution","translation_status":"translated"},"title_en":"A CSX EMD SD40-2 rolls out of a train yard in Walbridge, Ohio, with 47 freight cars, including some tank cars with flammable chemical, after its engineer fails to reboard it after setting a yard switch. It travels south driverless for 66 miles (106 km) until it was brought to a halt near Kenton .  The incident became the inspiration for the 2010 film Unstoppable .","title_ne":"ओहायोको वालब्रिजमा रहेको रेल यार्डबाट एउटा CSX EMD SD40-2 निस्कन्छ, जसमा ज्वलनशील रसायन भएका केही ट्याङ्क कारहरू सहित ४७ वटा मालवाहक कारहरू छन्, जब यसको इन्जिनियरले यार्ड स्विच सेट गरेपछि यसलाई पुन: बोर्ड गर्न असफल हुन्छ। यो केन्टन नजिकै रोकिएसम्म ६६ माइल (१०६ किलोमिटर) दक्षिणतिर चालकविहीन यात्रा गर्छ। यो घटना २०१० को फिल्म अनस्टप्पेबलको लागि प्रेरणा बन्यो।","highlight":false,"image_url":null,"published":true,"created_at":"2026-09-19T03:30:35.161956+00:00","event_type":"event","importance":65,"source_url":"https://en.wikipedia.org/wiki/CSX_Transportation","summary_en":null,"summary_ne":null,"updated_at":"2026-09-19T03:30:35.161956+00:00","source_name":"User-provided historical dataset","country_code":null,"image_credit":null,"image_api_url":"https://en.wikipedia.org/w/api.php?action=query&prop=pageimages&format=json&piprop=thumbnail%7Coriginal&pithumbsize=1200&titles=CSX%20Transportation&origin=*","image_license":null,"image_caption_en":null,"image_caption_ne":null,"image_page_title":"CSX Transportation","source_record_id":"0515-2001-e-3l4k5n","verification_status":"source-backed","event_date_precision":"day"}','2026-09-19T03:30:35.161956+00:00');
